    `;let{headers:t,rows:n,columnTypes:r}=Y.dataset,i=n;if(Y.previewSearch.trim()){let e=Y.previewSearch.trim().toLowerCase();i=n.filter(t=>t.some(t=>String(t).toLowerCase().includes(e)))}let a=i.length,o=i,s=``;if(e)o=i.slice(0,e);else{let e=Math.ceil(a/Y.pageSize)||1,t=Math.min(Y.previewPage,e),r=(t-1)*Y.pageSize,c=r+Y.pageSize;o=i.slice(r,c),s=`
